<?php declare(strict_types=1);
if(!$c['history'])return;
$clearingHistory=array_reverse($c['history']);$historyPages=(int)ceil(count($clearingHistory)/20);$historyRaw=input($_GET,'clearing_history_page','1');$historyValid=preg_match('/\A[1-9][0-9]{0,2}\z/D',$historyRaw)&&(int)$historyRaw<=$historyPages;$historyPage=$historyValid?(int)$historyRaw:1;
$historyUrl=static fn(int$page):string=>url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'clearings'=>'1','clearing_history_page'=>(string)$page]);
?>
<details class="card" data-balance-clearing-history <?= array_key_exists('clearing_history_page',$_GET)?'open':'' ?>><summary><?= e($clearingText('Entscheidungen zum Verrechnungsnachweis')) ?> (<?= count($clearingHistory) ?>)</summary>
<?php if(!$historyValid): ?><p role="alert"><?= e($clearingText('Verlaufsseite des Verrechnungsnachweises vollständig auswählen.')) ?></p><a class="btn btn-outline" href="<?= e($historyUrl(1)) ?>"><?= e($clearingText('Verlauf neu öffnen')) ?></a><?php else: ?>
<?php foreach(array_slice($clearingHistory,($historyPage-1)*20,20)as$h): ?><article><h3><?= e((new DateTimeImmutable($h['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' · '.$clearingText($h['state']==='reviewed'?'Bestätigt':'Vorbereitet')) ?></h3><p><?= e($h['note']) ?></p><a class="btn btn-outline" data-balance-clearing-history-link="<?= (int)$h['revision'] ?>" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'clearings'=>'1','clearing_original'=>(string)$h['revision'],'clearing_original_sha256'=>$h['sha256']])) ?>"><?= e($clearingText('Diesen ursprünglichen Ausgang lesen')) ?></a></article><?php endforeach ?>
<?php if($historyPages>1): ?><nav aria-label="<?= e($clearingText('Verlauf des Verrechnungsnachweises')) ?>"><p><?= e($clearingText('Seite')) ?> <?= $historyPage ?> / <?= $historyPages ?></p><?php if($historyPage>1): ?><a class="btn btn-outline" href="<?= e($historyUrl($historyPage-1)) ?>"><?= e($clearingText('Neuere Entscheidungen')) ?></a><?php endif ?><?php if($historyPage<$historyPages): ?><a class="btn btn-outline" href="<?= e($historyUrl($historyPage+1)) ?>"><?= e($clearingText('Frühere Entscheidungen')) ?></a><?php endif ?></nav><?php endif ?>
<?php endif ?></details>
